1	// Package dataparse holds the data-format parsers used both by datasource
2	// reading and by the data/conv function namespaces.
3	//
4	// YAML and TOML parsers are registered at init-time by the packages that
5	// implement them (internal/yaml, internal/toml) via RegisterYAML/RegisterTOML.
6	package dataparse
7	
8	import (
9		"bytes"
10		"encoding/csv"
11		"encoding/json"
12		"fmt"
13		"io"
14		"strings"
15	)
16	
17	// YAML parses YAML into interface{} (map[string]interface{}, []interface{},
18	// string, int, float64, bool, nil). Registered by internal/yaml.
19	var YAML func([]byte) (interface{}, error)
20	
21	// TOML parses TOML into interface{} (map[string]interface{}, []interface{},
22	// string, int64, float64, bool, time). Registered by internal/toml.
23	var TOML func([]byte) (interface{}, error)
24	
25	// MarshalYAML serializes a value as YAML. Registered by internal/yaml.
26	var MarshalYAML func(interface{}) ([]byte, error)
27	
28	// RegisterYAML installs the YAML parser/marshaler.
29	func RegisterYAML(parse func([]byte) (interface{}, error), marshal func(interface{}) ([]byte, error)) {
30		YAML = parse
31		MarshalYAML = marshal
32	}
33	
34	// RegisterTOML installs the TOML parser.
35	func RegisterTOML(parse func([]byte) (interface{}, error)) {
36		TOML = parse
37	}
38	
39	// JSON parses JSON, decoding numbers as int64 when integral, float64
40	// otherwise.
41	func JSON(b []byte) (interface{}, error) {
42		dec := json.NewDecoder(bytes.NewReader(b))
43		dec.UseNumber()
44		var v interface{}
45		if err := dec.Decode(&v); err != nil {
46			return nil, err
47		}
48		return convertJSONNumbers(v), nil
49	}
50	
51	// JSONArray parses a JSON document that must contain an array.
52	func JSONArray(b []byte) ([]interface{}, error) {
53		v, err := JSON(b)
54		if err != nil {
55			return nil, err
56		}
57		arr, ok := v.([]interface{})
58		if !ok {
59			return nil, fmt.Errorf("expected JSON array, got %T", v)
60		}
61		return arr, nil
62	}
63	
64	func convertJSONNumbers(v interface{}) interface{} {
65		switch t := v.(type) {
66		case map[string]interface{}:
67			for k, e := range t {
68				t[k] = convertJSONNumbers(e)
69			}
70			return t
71		case []interface{}:
72			for i, e := range t {
73				t[i] = convertJSONNumbers(e)
74			}
75			return t
76		case json.Number:
77			if i, err := t.Int64(); err == nil {
78				return i
79			}
80			if f, err := t.Float64(); err == nil {
81				return f
82			}
83			return t.String()
84		default:
85			return v
86		}
87	}
88	
89	// CSV parses CSV content into a row-first 2D string array. delim of 0 means
90	// the default (comma).
91	func CSV(delim rune, b []byte) ([][]string, error) {
92		r := csv.NewReader(bytes.NewReader(b))
93		if delim != 0 {
94			r.Comma = delim
95		}
96		return r.ReadAll()
97	}
98	
99	// EnvFile parses a .env-style file into a map of key/value pairs.
100	func EnvFile(b []byte) (map[string]string, error) {
101		out := map[string]string{}
102		src := strings.ReplaceAll(string(b), "\r\n", "\n")
103		for len(src) > 0 {
104			var line string
105			if i := strings.IndexByte(src, '\n'); i >= 0 {
106				line, src = src[:i], src[i+1:]
107			} else {
108				line, src = src, ""
109			}
110			line = strings.TrimSpace(line)
111			if line == "" || strings.HasPrefix(line, "#") {
112				continue
113			}
114			line = strings.TrimPrefix(line, "export ")
115			k, v, ok := strings.Cut(line, "=")
116			if !ok {
117				return nil, fmt.Errorf("can't separate key from value: %s", line)
118			}
119			key := strings.TrimSpace(k)
120			v = strings.TrimSpace(v)
121			if len(v) >= 2 && v[0] == '"' && v[len(v)-1] == '"' {
122				v = unescapeDoubleQuoted(v[1 : len(v)-1])
123			} else if len(v) >= 2 && v[0] == '\'' && v[len(v)-1] == '\'' {
124				v = v[1 : len(v)-1]
125			}
126			// variable expansion for ${VAR} and $VAR from earlier keys and OS env
127			v = expandEnvVars(v, out)
128			out[key] = v
129		}
130		return out, nil
131	}
132	
133	func unescapeDoubleQuoted(s string) string {
134		var sb strings.Builder
135		for i := 0; i < len(s); i++ {
136			if s[i] == '\\' && i+1 < len(s) {
137				i++
138				switch s[i] {
139				case 'n':
140					sb.WriteByte('\n')
141				case 't':
142					sb.WriteByte('\t')
143				case 'r':
144					sb.WriteByte('\r')
145				case '\\':
146					sb.WriteByte('\\')
147				case '"':
148					sb.WriteByte('"')
149				default:
150					sb.WriteByte('\\')
151					sb.WriteByte(s[i])
152				}
153				continue
154			}
155			sb.WriteByte(s[i])
156		}
157		return sb.String()
158	}
159	
160	func expandEnvVars(s string, local map[string]string) string {
161		var sb strings.Builder
162		for i := 0; i < len(s); i++ {
163			if s[i] == '$' && i+1 < len(s) {
164				if s[i+1] == '{' {
165					if j := strings.IndexByte(s[i:], '}'); j > 0 {
166						name := s[i+2 : i+j]
167						if v, ok := local[name]; ok {
168							sb.WriteString(v)
169						}
170						i += j
171						continue
172					}
173				}
174			}
175			sb.WriteByte(s[i])
176		}
177		return sb.String()
178	}
179	
180	// ReadAllString reads all of r as a string.
181	func ReadAllString(r io.Reader) (string, error) {
182		b, err := io.ReadAll(r)
183		return string(b), err
184	}

