// Package toml implements a TOML (https://toml.io) parser in pure Go,
// producing generic values compatible with gomplate's datasource handling:
// map[string]interface{}, []interface{}, string, int64, float64, bool and
// time.Time (for datetime/date/time values).
package toml

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/reimpl/gomplate/internal/dataparse"
)

func init() {
	dataparse.RegisterTOML(Unmarshal)
}

// Locations matching the zone names the reference implementation uses when
// printing local (offset-less) TOML datetime values.
var (
	locDatetimeLocal = time.FixedZone("datetime-local", 0)
	locDateLocal     = time.FixedZone("date-local", 0)
	locTimeLocal     = time.FixedZone("time-local", 0)
)

// Unmarshal parses a TOML document into generic Go values. The top-level
// result is always a map[string]interface{}.
func Unmarshal(b []byte) (interface{}, error) {
	p := &parser{
		data:      string(b),
		line:      1,
		root:      map[string]interface{}{},
		defined:   map[string]bool{},
		arrayTabs: map[string]bool{},
		finals:    map[string]bool{},
	}
	if err := p.parse(); err != nil {
		return nil, err
	}
	return p.root, nil
}

type parser struct {
	data string
	pos  int
	line int

	// lastKey is the absolute dotted path of the most recently parsed key,
	// used in error messages.
	lastKey string

	root    map[string]interface{}
	ctx     map[string]interface{}
	ctxPath []string

	defined   map[string]bool // paths of explicitly defined [tables]
	arrayTabs map[string]bool // paths of [[array of tables]]
	finals    map[string]bool // paths of inline tables (cannot be extended)
}

func (p *parser) errorf(format string, args ...interface{}) error {
	return fmt.Errorf("Near line %d (last key parsed '%s'): %s",
		p.line, p.lastKey, fmt.Sprintf(format, args...))
}

func (p *parser) eof() bool { return p.pos >= len(p.data) }

func (p *parser) peek() byte {
	if p.eof() {
		return 0
	}
	return p.data[p.pos]
}

func (p *parser) hasPrefix(s string) bool {
	return strings.HasPrefix(p.data[p.pos:], s)
}

// advance moves one byte forward, tracking line numbers.
func (p *parser) advance() {
	if p.pos < len(p.data) {
		if p.data[p.pos] == '\n' {
			p.line++
		}
		p.pos++
	}
}

func (p *parser) skipWhitespace() {
	for !p.eof() && (p.data[p.pos] == ' ' || p.data[p.pos] == '\t') {
		p.pos++
	}
}

func (p *parser) skipComment() {
	if p.peek() == '#' {
		for !p.eof() && p.data[p.pos] != '\n' {
			p.pos++
		}
	}
}

// skipWhitespaceComments skips whitespace, newlines and comments (used
// inside arrays, which may span lines).
func (p *parser) skipWhitespaceComments() {
	for !p.eof() {
		switch p.data[p.pos] {
		case ' ', '\t', '\r':
			p.pos++
		case '\n':
			p.advance()
		case '#':
			p.skipComment()
		default:
			return
		}
	}
}

func (p *parser) parse() error {
	p.ctx = p.root
	for {
		p.skipWhitespace()
		if p.eof() {
			return nil
		}
		switch c := p.peek(); {
		case c == '\n':
			p.advance()
		case c == '\r':
			p.pos++
		case c == '#':
			p.skipComment()
		case c == '[':
			if err := p.parseHeader(); err != nil {
				return err
			}
			if err := p.expectEndOfLine(); err != nil {
				return err
			}
		default:
			if err := p.parseKeyValue(p.ctx, p.ctxPath); err != nil {
				return err
			}
			if err := p.expectEndOfLine(); err != nil {
				return err
			}
		}
	}
}

func (p *parser) expectEndOfLine() error {
	p.skipWhitespace()
	if p.eof() {
		return nil
	}
	switch p.peek() {
	case '\n':
		p.advance()
		return nil
	case '\r':
		p.pos++
		return nil
	case '#':
		p.skipComment()
		return nil
	default:
		r, _ := utf8.DecodeRuneInString(p.data[p.pos:])
		return p.errorf("expected a top-level item to end with a newline, comment, or EOF, but got %q instead", r)
	}
}

// parseHeader parses a [table] or [[array-of-tables]] header.
func (p *parser) parseHeader() error {
	p.lastKey = ""
	p.pos++ // consume '['
	isArray := false
	if p.peek() == '[' {
		isArray = true
		p.pos++
	}
	p.skipWhitespace()
	key, err := p.parseKey()
	if err != nil {
		return err
	}
	p.skipWhitespace()
	if p.peek() != ']' {
		return p.errorf("expected ']' to end table name, but got %q instead", rune(p.peek()))
	}
	p.pos++
	if isArray {
		if p.peek() != ']' {
			return p.errorf("expected ']]' to end array of tables name, but got %q instead", rune(p.peek()))
		}
		p.pos++
	}
	return p.resolveHeader(key, isArray)
}

func joinPath(path []string) string { return strings.Join(path, ".") }

// resolveHeader locates (creating as needed) the table named by key and
// makes it the current context.
func (p *parser) resolveHeader(key []string, isArray bool) error {
	m := p.root
	var path []string
	for i, part := range key {
		last := i == len(key)-1
		if !last {
			existing, ok := m[part]
			if !ok {
				nm := map[string]interface{}{}
				m[part] = nm
				m = nm
				path = append(path, part)
				continue
			}
			path = append(path, part)
			switch e := existing.(type) {
			case map[string]interface{}:
				if p.finals[joinPath(path)] {
					return p.errorf("Key '%s' has already been defined.", joinPath(key))
				}
				m = e
			case []interface{}:
				if !p.arrayTabs[joinPath(path)] || len(e) == 0 {
					return p.errorf("Key '%s' is not a table", joinPath(key))
				}
				em, ok := e[len(e)-1].(map[string]interface{})
				if !ok {
					return p.errorf("Key '%s' is not a table", joinPath(key))
				}
				m = em
			default:
				return p.errorf("Key '%s' is not a table", joinPath(key))
			}
			continue
		}

		// last part of the key
		path = append(path, part)
		full := joinPath(path)
		existing, ok := m[part]
		if !ok {
			if isArray {
				nm := map[string]interface{}{}
				m[part] = []interface{}{nm}
				p.arrayTabs[full] = true
				p.ctx = nm
			} else {
				nm := map[string]interface{}{}
				m[part] = nm
				p.defined[full] = true
				p.ctx = nm
			}
			p.ctxPath = path
			return nil
		}
		switch e := existing.(type) {
		case map[string]interface{}:
			if isArray || p.defined[full] || p.finals[full] {
				return p.errorf("Key '%s' has already been defined.", full)
			}
			p.defined[full] = true
			p.ctx = e
		case []interface{}:
			if !isArray || !p.arrayTabs[full] {
				return p.errorf("Key '%s' has already been defined.", full)
			}
			nm := map[string]interface{}{}
			m[part] = append(e, nm)
			p.ctx = nm
		default:
			return p.errorf("Key '%s' has already been defined.", full)
		}
		p.ctxPath = path
		return nil
	}
	return nil
}

// parseKeyValue parses a `key = value` line and stores the value in m,
// resolving dotted keys.
func (p *parser) parseKeyValue(m map[string]interface{}, basePath []string) error {
	key, err := p.parseKey()
	if err != nil {
		return err
	}
	abs := append(append([]string{}, basePath...), key...)
	p.lastKey = joinPath(abs)
	p.skipWhitespace()
	if p.peek() != '=' {
		r, _ := utf8.DecodeRuneInString(p.data[p.pos:])
		return p.errorf("expected '.' or '=', but got %q instead", r)
	}
	p.pos++
	p.skipWhitespace()
	v, err := p.parseValue()
	if err != nil {
		return err
	}
	if err := p.setValue(m, basePath, key, v); err != nil {
		return err
	}
	return nil
}

// setValue stores v under the dotted key, creating intermediate tables.
func (p *parser) setValue(m map[string]interface{}, basePath, key []string, v interface{}) error {
	path := append(append([]string{}, basePath...))
	for i, part := range key {
		path = append(path, part)
		last := i == len(key)-1
		if last {
			if _, ok := m[part]; ok {
				return p.errorf("Key '%s' has already been defined.", joinPath(path))
			}
			m[part] = v
			return nil
		}
		existing, ok := m[part]
		if !ok {
			nm := map[string]interface{}{}
			m[part] = nm
			m = nm
			continue
		}
		nm, ok := existing.(map[string]interface{})
		if !ok {
			return p.errorf("Key '%s' is not a table", joinPath(path))
		}
		if p.finals[joinPath(path)] {
			return p.errorf("Key '%s' has already been defined.", joinPath(path))
		}
		m = nm
	}
	return nil
}

// markFinal marks the map (and nested maps) rooted at path as inline, so
// they cannot be extended by later keys.
func (p *parser) markFinal(path []string, v interface{}) {
	switch t := v.(type) {
	case map[string]interface{}:
		p.finals[joinPath(path)] = true
		for k, e := range t {
			p.markFinal(append(append([]string{}, path...), k), e)
		}
	case []interface{}:
		for _, e := range t {
			p.markFinal(path, e)
		}
	}
}

// parseKey parses a (possibly dotted) key.
func (p *parser) parseKey() ([]string, error) {
	var parts []string
	for {
		p.skipWhitespace()
		c := p.peek()
		var part string
		var err error
		switch {
		case c == '"':
			part, err = p.parseBasicString()
		case c == '\'':
			part, err = p.parseLiteralString()
		case isBareKeyChar(c):
			start := p.pos
			for !p.eof() && isBareKeyChar(p.data[p.pos]) {
				p.pos++
			}
			part = p.data[start:p.pos]
		default:
			r, _ := utf8.DecodeRuneInString(p.data[p.pos:])
			return nil, p.errorf("expected '.' or '=', but got %q instead", r)
		}
		if err != nil {
			return nil, err
		}
		parts = append(parts, part)
		p.skipWhitespace()
		if p.peek() == '.' {
			p.pos++
			continue
		}
		return parts, nil
	}
}

func isBareKeyChar(c byte) bool {
	return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '-' || c == '_'
}

func (p *parser) parseValue() (interface{}, error) {
	p.skipWhitespace()
	if p.eof() {
		return nil, p.errorf("expected value but found EOF instead")
	}
	switch c := p.peek(); {
	case c == '"':
		return p.parseBasicString()
	case c == '\'':
		return p.parseLiteralString()
	case c == '[':
		return p.parseArray()
	case c == '{':
		return p.parseInlineTable()
	default:
		return p.parseScalar()
	}
}

// scanToken reads a scalar token up to the next delimiter.
func (p *parser) scanToken() string {
	start := p.pos
	for !p.eof() {
		switch p.data[p.pos] {
		case ' ', '\t', '\r', '\n', '#', ',', ']', '}':
			return p.data[start:p.pos]
		}
		p.pos++
	}
	return p.data[start:p.pos]
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

// parseScalar parses booleans, numbers and datetime values.
func (p *parser) parseScalar() (interface{}, error) {
	tok := p.scanToken()

	switch tok {
	case "true":
		return true, nil
	case "false":
		return false, nil
	}

	// datetimes: a date optionally followed by a whitespace-separated time
	if isDateShape(tok) {
		save := p.pos
		p.skipWhitespace()
		if !p.eof() && isDigit(p.peek()) {
			if tok2 := p.scanToken(); isTimeShapePrefix(tok2) {
				tok = tok + " " + tok2
			} else {
				p.pos = save
			}
		} else {
			p.pos = save
		}
		return p.parseDatetime(tok)
	}
	if isTimeShapePrefix(tok) {
		return p.parseDatetime(tok)
	}

	// inf / nan
	switch tok {
	case "inf", "+inf":
		return math.Inf(1), nil
	case "-inf":
		return math.Inf(-1), nil
	case "nan", "+nan", "-nan":
		return math.NaN(), nil
	}

	// hex / octal / binary integers (no sign allowed)
	if strings.HasPrefix(tok, "0x") || strings.HasPrefix(tok, "0o") || strings.HasPrefix(tok, "0b") {
		return p.parseBaseInt(tok)
	}
	if len(tok) > 3 && (tok[0] == '+' || tok[0] == '-') &&
		(tok[1] == '0' && (tok[2] == 'x' || tok[2] == 'o' || tok[2] == 'b')) {
		return nil, p.errorf("cannot use sign with non-decimal numbers: '%s'", tok[:3])
	}

	// decimal integer
	if isDecIntShape(tok) {
		return p.parseDecInt(tok)
	}

	// float
	if isFloatShape(tok) {
		f, err := strconv.ParseFloat(strings.ReplaceAll(tok, "_", ""), 64)
		if err != nil {
			return nil, p.errorf("Invalid float %q", tok)
		}
		return f, nil
	}

	return nil, p.errorf("expected value but found %q instead", tok)
}

func isDateShape(tok string) bool {
	return len(tok) == 10 && isDigit(tok[0]) && isDigit(tok[1]) && isDigit(tok[2]) && isDigit(tok[3]) &&
		tok[4] == '-' && isDigit(tok[5]) && isDigit(tok[6]) && tok[7] == '-' && isDigit(tok[8]) && isDigit(tok[9])
}

func isTimeShapePrefix(tok string) bool {
	return len(tok) >= 5 && isDigit(tok[0]) && isDigit(tok[1]) && tok[2] == ':' && isDigit(tok[3]) && isDigit(tok[4])
}

// isDecIntShape reports whether tok is [+-]?DIGIT(_?DIGIT)*
func isDecIntShape(tok string) bool {
	i := 0
	if i < len(tok) && (tok[i] == '+' || tok[i] == '-') {
		i++
	}
	if i >= len(tok) || !isDigit(tok[i]) {
		return false
	}
	underscore := false
	for i++; i < len(tok); i++ {
		switch {
		case isDigit(tok[i]):
			underscore = false
		case tok[i] == '_' && !underscore:
			underscore = true
		default:
			return false
		}
	}
	return !underscore
}

// isFloatShape reports whether tok is a valid TOML float:
// [+-]? int ( frac )? ( exp )?  with at least one of frac/exp present.
func isFloatShape(tok string) bool {
	i := 0
	if i < len(tok) && (tok[i] == '+' || tok[i] == '-') {
		i++
	}
	n := scanDigits(tok, i)
	if n == i {
		return false
	}
	i = n
	isFloat := false
	if i < len(tok) && tok[i] == '.' {
		isFloat = true
		i++
		n = scanDigits(tok, i)
		if n == i {
			return false
		}
		i = n
	}
	if i < len(tok) && (tok[i] == 'e' || tok[i] == 'E') {
		isFloat = true
		i++
		if i < len(tok) && (tok[i] == '+' || tok[i] == '-') {
			i++
		}
		n = scanDigits(tok, i)
		if n == i {
			return false
		}
		i = n
	}
	return isFloat && i == len(tok)
}

// scanDigits scans DIGIT(_?DIGIT)* starting at i, returning the end index.
func scanDigits(s string, i int) int {
	if i >= len(s) || !isDigit(s[i]) {
		return i
	}
	i++
	for i < len(s) {
		if isDigit(s[i]) {
			i++
		} else if s[i] == '_' && i+1 < len(s) && isDigit(s[i+1]) {
			i += 2
		} else {
			break
		}
	}
	return i
}

func (p *parser) parseDecInt(tok string) (interface{}, error) {
	clean := strings.ReplaceAll(tok, "_", "")
	// leading zeroes are not allowed
	digits := strings.TrimLeft(clean, "+-")
	if len(digits) > 1 && digits[0] == '0' {
		return nil, p.errorf("Invalid integer %q: cannot have leading zeroes", tok)
	}
	i, err := strconv.ParseInt(clean, 10, 64)
	if err != nil {
		return nil, p.errorf("Integer '%s' is out of the range of 64-bit signed integers.", tok)
	}
	return i, nil
}

func (p *parser) parseBaseInt(tok string) (interface{}, error) {
	base := 16
	switch tok[1] {
	case 'o':
		base = 8
	case 'b':
		base = 2
	}
	digits := tok[2:]
	if digits == "" {
		return nil, p.errorf("Invalid integer %q: no digits", tok)
	}
	for i := 0; i < len(digits); i++ {
		c := digits[i]
		if c == '_' {
			if i == 0 || i == len(digits)-1 || digits[i-1] == '_' {
				return nil, p.errorf("Invalid integer %q: underscores must be surrounded by digits", tok)
			}
			continue
		}
	}
	i, err := strconv.ParseInt(strings.ReplaceAll(digits, "_", ""), base, 64)
	if err != nil {
		return nil, p.errorf("Invalid integer %q", tok)
	}
	return i, nil
}

// parseDatetime parses TOML datetime values into time.Time.
func (p *parser) parseDatetime(tok string) (interface{}, error) {
	bad := func() (interface{}, error) {
		return nil, p.errorf("Invalid TOML Datetime: %q.", tok)
	}

	var year, month, day, hour, min, sec, nsec int
	var err error
	rest := tok
	hasDate, hasTime := false, false

	if len(rest) >= 10 && rest[4] == '-' && rest[7] == '-' {
		hasDate = true
		if year, err = atoiN(rest[0:4]); err != nil {
			return bad()
		}
		if month, err = atoiN(rest[5:7]); err != nil {
			return bad()
		}
		if day, err = atoiN(rest[8:10]); err != nil {
			return bad()
		}
		rest = rest[10:]
		if month < 1 || month > 12 || day < 1 || day > daysIn(month, year) {
			return bad()
		}
		if rest != "" {
			if rest[0] != 'T' && rest[0] != 't' && rest[0] != ' ' {
				return bad()
			}
			rest = rest[1:]
		}
	}

	if rest != "" {
		hasTime = true
		if len(rest) < 8 || rest[2] != ':' || rest[5] != ':' {
			return bad()
		}
		if hour, err = atoiN(rest[0:2]); err != nil {
			return bad()
		}
		if min, err = atoiN(rest[3:5]); err != nil {
			return bad()
		}
		if sec, err = atoiN(rest[6:8]); err != nil {
			return bad()
		}
		rest = rest[8:]
		if hour > 23 || min > 59 || sec > 59 {
			return bad()
		}
		if rest != "" && rest[0] == '.' {
			i := 1
			for i < len(rest) && isDigit(rest[i]) {
				i++
			}
			if i == 1 {
				return bad()
			}
			frac := rest[1:i]
			if len(frac) > 9 {
				frac = frac[:9]
			}
			for len(frac) < 9 {
				frac += "0"
			}
			if nsec, err = atoiN(frac); err != nil {
				return bad()
			}
			rest = rest[i:]
		}
	}

	if !hasDate && !hasTime {
		return bad()
	}

	// local time only
	if !hasDate {
		if rest != "" {
			return bad()
		}
		return time.Date(0, 1, 1, hour, min, sec, nsec, locTimeLocal), nil
	}
	if !hasTime {
		if rest != "" {
			return bad()
		}
		return time.Date(year, time.Month(month), day, 0, 0, 0, 0, locDateLocal), nil
	}

	// optional offset
	if rest == "" {
		return time.Date(year, time.Month(month), day, hour, min, sec, nsec, locDatetimeLocal), nil
	}
	if rest == "Z" || rest == "z" {
		return time.Date(year, time.Month(month), day, hour, min, sec, nsec, time.UTC), nil
	}
	if len(rest) == 6 && (rest[0] == '+' || rest[0] == '-') && rest[3] == ':' {
		oh, err1 := atoiN(rest[1:3])
		om, err2 := atoiN(rest[4:6])
		if err1 != nil || err2 != nil || oh > 23 || om > 59 {
			return bad()
		}
		offset := oh*3600 + om*60
		if rest[0] == '-' {
			offset = -offset
		}
		if offset == 0 {
			return time.Date(year, time.Month(month), day, hour, min, sec, nsec, time.UTC), nil
		}
		sign := byte('+')
		if offset < 0 {
			sign = '-'
			oh, om = -oh, -om
		}
		name := fmt.Sprintf("%c%02d%02d", sign, oh, om)
		return time.Date(year, time.Month(month), day, hour, min, sec, nsec,
			time.FixedZone(name, offset)), nil
	}
	return bad()
}

func atoiN(s string) (int, error) {
	n := 0
	for i := 0; i < len(s); i++ {
		if !isDigit(s[i]) {
			return 0, fmt.Errorf("not a number: %q", s)
		}
		n = n*10 + int(s[i]-'0')
	}
	return n, nil
}

func daysIn(month, year int) int {
	switch month {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	case 2:
		if year%4 == 0 && (year%100 != 0 || year%400 == 0) {
			return 29
		}
		return 28
	}
	return 0
}

// parseBasicString parses "..." and """...""" strings.
func (p *parser) parseBasicString() (string, error) {
	if p.hasPrefix(`"""`) {
		return p.parseMultilineBasicString()
	}
	p.pos++ // opening quote
	var sb strings.Builder
	for {
		if p.eof() {
			return "", p.errorf("unexpected EOF; expected '\"'")
		}
		switch c := p.data[p.pos]; {
		case c == '"':
			p.pos++
			return sb.String(), nil
		case c == '\n':
			return "", p.errorf("strings cannot contain newlines")
		case c == '\\':
			if err := p.parseEscape(&sb, false); err != nil {
				return "", err
			}
		default:
			sb.WriteByte(c)
			p.pos++
		}
	}
}

func (p *parser) parseMultilineBasicString() (string, error) {
	p.pos += 3 // opening """
	// a newline immediately after the opening delimiter is trimmed
	if p.hasPrefix("\r\n") {
		p.pos += 2
		p.line++
	} else if p.peek() == '\n' {
		p.advance()
	}
	var sb strings.Builder
	for {
		if p.eof() {
			return "", p.errorf(`unexpected EOF; expected '"""'`)
		}
		switch c := p.data[p.pos]; {
		case c == '"':
			n := 0
			for p.pos+n < len(p.data) && p.data[p.pos+n] == '"' {
				n++
			}
			if n >= 3 {
				sb.WriteString(strings.Repeat(`"`, n-3))
				p.pos += n
				return sb.String(), nil
			}
			sb.WriteString(strings.Repeat(`"`, n))
			p.pos += n
		case c == '\\':
			if err := p.parseEscape(&sb, true); err != nil {
				return "", err
			}
		default:
			sb.WriteByte(c)
			p.advance()
		}
	}
}

// parseEscape handles a backslash escape; pos is at the backslash.
func (p *parser) parseEscape(sb *strings.Builder, multiline bool) error {
	p.pos++ // backslash
	if p.eof() {
		return p.errorf("unexpected EOF; expected escape sequence")
	}
	c := p.data[p.pos]
	// line-ending backslash: skip all following whitespace incl. newlines
	if multiline && (c == ' ' || c == '\t' || c == '\r' || c == '\n') {
		for !p.eof() {
			switch p.data[p.pos] {
			case ' ', '\t', '\r':
				p.pos++
			case '\n':
				p.advance()
			default:
				return nil
			}
		}
		return nil
	}
	p.pos++
	switch c {
	case 'b':
		sb.WriteByte('\b')
	case 't':
		sb.WriteByte('\t')
	case 'n':
		sb.WriteByte('\n')
	case 'f':
		sb.WriteByte('\f')
	case 'r':
		sb.WriteByte('\r')
	case '"':
		sb.WriteByte('"')
	case '\\':
		sb.WriteByte('\\')
	case 'u', 'U':
		n := 4
		if c == 'U' {
			n = 8
		}
		if p.pos+n > len(p.data) {
			return p.errorf("invalid escape sequence '\\%c%s'", c, p.data[p.pos:])
		}
		hex := p.data[p.pos : p.pos+n]
		v, err := strconv.ParseUint(hex, 16, 32)
		if err != nil || !utf8.ValidRune(rune(v)) {
			return p.errorf("invalid escape sequence '\\%c%s'", c, hex)
		}
		p.pos += n
		sb.WriteRune(rune(v))
	default:
		return p.errorf("invalid escape character %q; only the following escape characters are allowed: "+
			`\\b, \\t, \\n, \\f, \\r, \\", \\\\, \\uXXXX, and \\UXXXXXXXX`, c)
	}
	return nil
}

// parseLiteralString parses '...' and '''...''' strings.
func (p *parser) parseLiteralString() (string, error) {
	if p.hasPrefix(`'''`) {
		return p.parseMultilineLiteralString()
	}
	p.pos++ // opening quote
	var sb strings.Builder
	for {
		if p.eof() {
			return "", p.errorf("unexpected EOF; expected \"'\"")
		}
		switch c := p.data[p.pos]; {
		case c == '\'':
			p.pos++
			return sb.String(), nil
		case c == '\n':
			return "", p.errorf("strings cannot contain newlines")
		default:
			sb.WriteByte(c)
			p.pos++
		}
	}
}

func (p *parser) parseMultilineLiteralString() (string, error) {
	p.pos += 3 // opening '''
	if p.hasPrefix("\r\n") {
		p.pos += 2
		p.line++
	} else if p.peek() == '\n' {
		p.advance()
	}
	var sb strings.Builder
	for {
		if p.eof() {
			return "", p.errorf(`unexpected EOF; expected "'''"`)
		}
		if c := p.data[p.pos]; c == '\'' {
			n := 0
			for p.pos+n < len(p.data) && p.data[p.pos+n] == '\'' {
				n++
			}
			if n >= 3 {
				sb.WriteString(strings.Repeat(`'`, n-3))
				p.pos += n
				return sb.String(), nil
			}
			sb.WriteString(strings.Repeat(`'`, n))
			p.pos += n
			continue
		}
		sb.WriteByte(p.data[p.pos])
		p.advance()
	}
}

// parseArray parses [ ... ] arrays, which may span multiple lines.
func (p *parser) parseArray() (interface{}, error) {
	p.pos++ // consume '['
	arr := []interface{}{}
	for {
		p.skipWhitespaceComments()
		if p.eof() {
			return nil, p.errorf("unexpected EOF; expected ']'")
		}
		if p.peek() == ']' {
			p.pos++
			return arr, nil
		}
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		arr = append(arr, v)
		p.skipWhitespaceComments()
		if p.eof() {
			return nil, p.errorf("unexpected EOF; expected ']'")
		}
		switch p.peek() {
		case ',':
			p.pos++
		case ']':
			p.pos++
			return arr, nil
		default:
			r, _ := utf8.DecodeRuneInString(p.data[p.pos:])
			return nil, p.errorf("expected a comma (',') or array terminator (']'), but got %q instead", r)
		}
	}
}

// parseInlineTable parses { key = value, ... } inline tables.
func (p *parser) parseInlineTable() (interface{}, error) {
	p.pos++ // consume '{'
	m := map[string]interface{}{}
	p.skipWhitespace()
	if p.peek() == '}' {
		p.pos++
		return m, nil
	}
	for {
		if err := p.parseKeyValue(m, nil); err != nil {
			return nil, err
		}
		p.skipWhitespace()
		if p.eof() {
			return nil, p.errorf("unexpected EOF; expected '}'")
		}
		switch p.peek() {
		case ',':
			p.pos++
			p.skipWhitespace()
			if p.peek() == '}' {
				return nil, p.errorf("trailing comma not allowed in inline tables")
			}
		case '}':
			p.pos++
			return m, nil
		default:
			r, _ := utf8.DecodeRuneInString(p.data[p.pos:])
			return nil, p.errorf("expected a comma (',') or inline table terminator ('}'), but got %q instead", r)
		}
	}
}

